// Prepare LLM prompt payload with editorial guidelines & guardrails
const item = $input.first().json;
const candidate = item.candidate || item;

const systemPrompt = `Você é o Editor Chefe do Avalia Solar (@avalia_solar), a maior plataforma de transparência, avaliação e cotações de energia solar do Brasil.
Sua missão é transformar artigos técnicos em posts educativos de alta autoridade para o feed do Instagram.

DIRETRIZES EDITORIAIS:
- Tom: Técnico, transparente, empoderador, analítico e direto ao ponto.
- Proibido: Clickbait apelativo, promessas irreais ('ganhe energia de graça'), termos pejorativos ou dados sem embasamento.
- Contexto regulatório: Conhecimento exato de GD, Lei 14.300, Aneel, micro/minigeração e Mercado Livre de Energia.
- Formato: Retorne ESTRITAMENTE um objeto JSON válido.`;

const userPrompt = `Transforme este artigo em um post para o Instagram:\nTítulo: ${candidate.title}\nCategoria: ${candidate.category}\nResumo: ${candidate.summary}\nConteúdo: ${candidate.content}\nURL Canônica: ${candidate.canonical_url}\n\nRetorne estritamente um JSON com:\n{\n  "headline": "Título curto e impactante para o card visual (máx 60 caracteres)",\n  "hook": "Gancho inicial intrigante para a primeira linha da legenda (máx 100 caracteres)",\n  "context": "Contextualização do cenário atual de energia (máx 250 caracteres)",\n  "explanation": "Explicação prática e transparente de como funciona ou impacto real (máx 450 caracteres)",\n  "insight": "Recomendação prática para o consumidor ou integrador (máx 200 caracteres)",\n  "cta": "Chamada para ação clara (ex: 'Calcule sua economia no link da bio')",\n  "hashtags": ["#energiasolar", "#avaliasolar", "#fotovoltaico", "#economiadeenergia", "#sustentabilidade"]\n}`;

return [{
  json: {
    candidate,
    systemPrompt,
    userPrompt,
    openai_key: $env.OPENAI_API_KEY || ''
  }
}];

// Validate JSON schema, sanitize and assemble caption
const response = $input.first().json;
const promptData = $('Format Editorial Prompt').first().json;
const rawContent = response.choices?.[0]?.message?.content || '{}';

let editorial;
try {
  editorial = JSON.parse(rawContent);
} catch (e) {
  throw new Error(`Failed to parse AI output: ${e.message} - Raw: ${rawContent}`);
}

const headline = (editorial.headline || promptData.candidate.title).slice(0, 80);
const hook = (editorial.hook || '').trim();
const context = (editorial.context || '').trim();
const explanation = (editorial.explanation || '').trim();
const insight = (editorial.insight || '').trim();
const cta = (editorial.cta || 'Confira a análise completa no link da bio.').trim();
const hashtags = Array.isArray(editorial.hashtags) ? editorial.hashtags : ['#energiasolar', '#avaliasolar'];

const fullCaption = `${hook}\n\n${context}\n\n${explanation}\n\n💡 Insight Avalia Solar:\n${insight}\n\n👉 ${cta}\n🔗 Leia a matéria na íntegra: ${promptData.candidate.canonical_url}\n\n.\n.\n.\n${hashtags.join(' ')}`;

return [{
  json: {
    status: 'EDITORIAL_READY',
    candidate: promptData.candidate,
    headline,
    full_caption: fullCaption,
    editorial,
    category: promptData.candidate.category,
    canonical_url: promptData.candidate.canonical_url,
    generated_at: new Date().toISOString()
  }
}];
